  return [...token.text].map((glyph,glyphIndex)=><span key={glyphIndex} className="g4l8-in007__glyph" data-source-native-glyph={glyphIndex} style={{color:`rgb(${token.nativeGlyphPaints![glyphIndex].join(',')})`}}>{glyph}{token.nativeGlyphForegrounds?.filter(layer=>layer.glyphIndex===glyphIndex&&curveAt(layer.alpha,state.frame)>0).map(layer=><span key={layer.sourceInstance} aria-hidden="true" className="g4l8-in007__foreground" data-native-foreground={layer.text} data-source-foreground-character={layer.sourceCharacter} data-source-foreground-instance={layer.sourceInstance} data-source-foreground-depth={layer.sourceDepth} data-source-offset-twips={layer.sourceOffsetTwips.join(',')} style={{zIndex:layer.sourceDepth,opacity:curveAt(layer.alpha,state.frame),color:`rgb(${curveAt(layer.rgb,state.frame).join(',')})`,transform:`translate(${layer.offsetEm[0]}em,${layer.offsetEm[1]}em)`}}/>)}</span>);
